#!/usr/bin/env python3
"""Regenerate or check the paginated survey discovery index offline."""

import argparse
from collections import Counter
import sys

from catalog import ROOT, cell, markdown_url, read_validated
from discovery import CLASSES, load_discovery


def render(rows: list[dict]) -> dict:
    counts = Counter(row['class'] for row in rows)
    checks = Counter(row['source_check'] for row in rows)
    lines = [
        '# Extended Discovery Index', '',
        '<!-- Generated by scripts/generate_discovery.py; edit data/discovery.json instead. -->', '',
        f'**{len(rows)} survey-discovered works**, grouped by boundary/comparison role.', '',
        'This layer adapts the author-provided survey discovery snapshot (search cutoff 2026-10-07).',
        'It is broader than the curated catalog. The two layers overlap; do not add their counts.',
        'A cataloged work is not necessarily a distinct system, deployment, or reproduced result.', '',
        f"Source checks: {checks['metadata-verified']} metadata-verified; {checks['reachable']} reachable; {checks['reference-only']} reference-only.", '',
        '- **metadata-verified:** identity checked on official arXiv or DOI-registry metadata.',
        '- **reachable:** the primary source opened; this is not a full technical or publication-status audit.',
        '- **reference-only:** a supplied primary link remains, but this pass could not independently check its identity/access.', '',
        'Publication labels imported from the survey are kept separately as survey-reported metadata.',
        'Descriptions and boundary placement are survey-derived editorial annotations, not independently re-coded system properties.',
        'For curated contribution/scope notes, use the linked curated entry where available.', '',
        '[Boundary guide](boundary-guide.md) · [Curated catalog](catalog.md) · [Source policy](sources.md)', '',
        '## Browse', '',
    ]
    outputs = {}
    for cls, (slug, title) in CLASSES.items():
        group = sorted((r for r in rows if r['class'] == cls), key=lambda r: (-r['year'], r['title'].casefold(), r['id']))
        lines.append(f'- [{cls}: {title}](discovery/{slug}.md) — {counts[cls]} works')
        page = [f'# {cls}: {title}', '', '<!-- Generated; edit data/discovery.json instead. -->', '',
                f'{len(group)} discovery records. [Index and evidence policy](../discovery.md).', '',
                'Subtypes and descriptions below are inherited survey classifications; source metadata checks do not validate the technical classification.', '',
                '| Year / subtype | Work and sources | Source check | Boundary or comparison note |',
                '|---|---|---|---|']
        for r in group:
            work = f"<a name=\"{r['id']}\"></a>[{cell(r['title'])}]({markdown_url(r['source'])})"
            if r.get('aliases'):
                work += '<br>Also indexed as: ' + cell(', '.join(r['aliases']))
            if r.get('main_id'):
                work += f"<br>[Curated entry](../catalog.md#{r['main_id']})"
            if r.get('code'):
                work += f" · [Artifact]({markdown_url(r['code'])})"
            page.append(f"| {r['year']} / {r['subtype']} | {work} | {r['source_check']} | {cell(r['why_it_matters'])} |")
        outputs[ROOT / 'docs' / 'discovery' / f'{slug}.md'] = '\n'.join(page) + '\n'
    lines.extend(['', '## Search locally', '', '```bash',
                  'python3 scripts/search_papers.py --collection discovery --class O',
                  'python3 scripts/search_papers.py --collection all "elastic"',
                  'python3 scripts/search_papers.py --collection discovery --year 2026 --json',
                  '```', '',
                  'The combined collection keeps a curated record instead of its mapped discovery counterpart. Distinct reports about one system can remain separate works.',
                  'Filters can match either representation before deduplication; the returned curated record can therefore use a corrected category/year or different tags from its discovery match.',
                  'Use `--collection discovery` to inspect historical survey classification and source-check state explicitly.', ''])
    outputs[ROOT / 'docs' / 'discovery.md'] = '\n'.join(lines)
    return outputs


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument('--write', action='store_true')
    mode.add_argument('--check', action='store_true')
    args = parser.parse_args()
    try:
        papers = read_validated()
        rows = load_discovery({p['id'] for p in papers})
        outputs = render(rows)
        if args.write:
            for path, content in outputs.items():
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding='utf-8')
            print(f'Wrote {len(outputs)} discovery pages for {len(rows)} records.')
        else:
            stale = [str(p.relative_to(ROOT)) for p, s in outputs.items() if not p.is_file() or p.read_text(encoding='utf-8') != s]
            if stale:
                raise ValueError('Missing or stale discovery pages: ' + ', '.join(stale))
            print(f'Discovery: {len(rows)} records; generated pages current.')
    except (OSError, ValueError) as exc:
        print(exc, file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
